-- Foundation schema, additive initial migration. IDs generated by Prisma.
CREATE TABLE "User" (
 "id" TEXT NOT NULL,
 "email" TEXT NOT NULL,
 "passwordHash" TEXT NOT NULL,
 "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT "User_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "Shoot" (
 "id" TEXT NOT NULL,
 "ownerId" TEXT NOT NULL,
 "name" TEXT NOT NULL,
 "data" JSONB NOT NULL,
 "revision" INTEGER NOT NULL DEFAULT 1,
 "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 "updatedAt" TIMESTAMP(3) NOT NULL,
 "deletedAt" TIMESTAMP(3),
 CONSTRAINT "Shoot_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE INDEX "Shoot_ownerId_updatedAt_idx" ON "Shoot"("ownerId", "updatedAt");
ALTER TABLE "Shoot" ADD CONSTRAINT "Shoot_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
